/*
 * Chip bring-up console: firmware of the board's MCU (STM32F407, bare metal).
 *
 * It releases the chip from reset (a chip in Forge's register harness is held there after
 * power-up) and answers on its console UART, one command per line:
 *
 *   PING                     -> PONG
 *   INFO                     -> INFO chip=<register 0> fw=1.0
 *   READ <offset>            -> VALUE offset=<offset> value=<value>
 *   WRITE <offset> <value>   -> OK offset=<offset> value=<value>
 *
 * Numbers are decimal or 0x hexadecimal; offsets are multiples of 4. board.h is generated by
 * Chipova Forge from system.yaml; forge_chip.h reaches the chip's registers however the board
 * wires the chip.
 */
#include <stdint.h>

#include "board.h"
#include "forge_chip.h"
#include "stm32f4_min.h"

#define FW_VERSION "1.0"

static volatile uint32_t ticks_ms;

#define RX_SIZE 128
static volatile char rx_buf[RX_SIZE];
static volatile unsigned rx_head, rx_tail;

static void uart_putc(char c)
{
    while (!(USART_SR(BOARD_UART) & USART_SR_TXE)) {}
    USART_DR(BOARD_UART) = (uint8_t)c;
}

static void uart_puts(const char *s)
{
    while (*s) uart_putc(*s++);
}

static void uart_putu(uint32_t u)
{
    char tmp[11];
    int n = 0;
    do { tmp[n++] = (char)('0' + u % 10u); u /= 10u; } while (u);
    while (n) uart_putc(tmp[--n]);
}

static void uart_puthex(uint32_t v)
{
    uart_puts("0x");
    for (int i = 28; i >= 0; i -= 4) uart_putc("0123456789abcdef"[(v >> i) & 0xFu]);
}

void BOARD_UART_IRQHandler(void)
{
    if (USART_SR(BOARD_UART) & USART_SR_RXNE) {
        char c = (char)USART_DR(BOARD_UART);
        unsigned next = (rx_head + 1u) % RX_SIZE;
        if (next != rx_tail) {
            rx_buf[rx_head] = c;
            rx_head = next;
        }
    }
}

static int uart_getc(char *c)
{
    if (rx_tail == rx_head) return 0;
    *c = rx_buf[rx_tail];
    rx_tail = (rx_tail + 1u) % RX_SIZE;
    return 1;
}

void SysTick_Handler(void) { ticks_ms++; }

/* A decimal or 0x hexadecimal number; returns the text after it, or 0 if there is none. */
static const char *parse_u32(const char *s, uint32_t *out)
{
    uint32_t v = 0;
    int any = 0;
    while (*s == ' ') s++;
    if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) {
        s += 2;
        for (;; s++) {
            char c = *s;
            uint32_t d;
            if (c >= '0' && c <= '9') d = (uint32_t)(c - '0');
            else if (c >= 'a' && c <= 'f') d = (uint32_t)(c - 'a' + 10);
            else if (c >= 'A' && c <= 'F') d = (uint32_t)(c - 'A' + 10);
            else break;
            v = (v << 4) | d;
            any = 1;
        }
    } else {
        while (*s >= '0' && *s <= '9') { v = v * 10u + (uint32_t)(*s++ - '0'); any = 1; }
    }
    if (!any) return 0;
    *out = v;
    return s;
}

static int starts_with(const char *s, const char *prefix)
{
    while (*prefix) {
        char a = *s++, b = *prefix++;
        if (a >= 'a' && a <= 'z') a = (char)(a - 32);
        if (a != b) return 0;
    }
    return 1;
}

static void handle_line(const char *line)
{
    uint32_t off, val;
    const char *rest;
    if (starts_with(line, "PING")) {
        uart_puts("PONG\r\n");
    } else if (starts_with(line, "INFO")) {
        uart_puts("INFO chip=");
        uart_puthex(chip_read(0));
        uart_puts(" fw=" FW_VERSION "\r\n");
    } else if (starts_with(line, "READ")) {
        if (!(rest = parse_u32(line + 4, &off)) || (off & 3u) || off > 252u) { uart_puts("ERR bad offset\r\n"); return; }
        val = chip_read(off);
        uart_puts("VALUE offset=");
        uart_putu(off);
        uart_puts(" value=");
        uart_putu(val);
        uart_puts("\r\n");
    } else if (starts_with(line, "WRITE")) {
        if (!(rest = parse_u32(line + 5, &off)) || (off & 3u) || off > 252u) { uart_puts("ERR bad offset\r\n"); return; }
        if (!parse_u32(rest, &val)) { uart_puts("ERR bad value\r\n"); return; }
        chip_write(off, val);
        uart_puts("OK offset=");
        uart_putu(off);
        uart_puts(" value=");
        uart_putu(val);
        uart_puts("\r\n");
    } else if (line[0]) {
        uart_puts("ERR unknown command\r\n");
    }
}

static void gpio_mode(uint32_t port, unsigned pin, uint32_t mode)
{
    GPIO_MODER(port) = (GPIO_MODER(port) & ~(3u << (2 * pin))) | (mode << (2 * pin));
}

static void gpio_af(uint32_t port, unsigned pin, uint32_t af)
{
    gpio_mode(port, pin, 2u);
    if (pin < 8) GPIO_AFRL(port) = (GPIO_AFRL(port) & ~(0xFu << (4 * pin))) | (af << (4 * pin));
    else GPIO_AFRH(port) = (GPIO_AFRH(port) & ~(0xFu << (4 * (pin - 8)))) | (af << (4 * (pin - 8)));
}

int main(void)
{
    RCC_AHB1ENR |= 0x1FFu;
    gpio_mode(BOARD_LED_HEARTBEAT_PORT, BOARD_LED_HEARTBEAT_PIN, 1u);
    BOARD_UART_CLOCK_ON();
    gpio_af(BOARD_UART_TX_PORT, BOARD_UART_TX_PIN, BOARD_UART_AF);
    gpio_af(BOARD_UART_RX_PORT, BOARD_UART_RX_PIN, BOARD_UART_AF);
    USART_BRR(BOARD_UART) = 16000000u / 115200u;
    USART_CR1(BOARD_UART) = USART_CR1_UE | USART_CR1_TE | USART_CR1_RE | USART_CR1_RXNEIE;
    nvic_enable(BOARD_UART_IRQn);
    SYST_RVR = 16000000u / 1000u - 1u;
    SYST_CVR = 0;
    SYST_CSR = 7u;

    chip_init();
#ifdef BOARD_CHIP_HARNESS
    chip_write(0x04, 0); /* the harness's CONTROL: let the chip run */
#endif
    uart_puts("READY bring-up chip=");
    uart_puthex(chip_read(0));
    uart_puts(" fw=" FW_VERSION "\r\n");

    char line[64];
    unsigned len = 0;
    uint32_t next_blink = 0;
    for (;;) {
        if ((int32_t)(ticks_ms - next_blink) >= 0) {
            next_blink = ticks_ms + 500u;
            GPIO_ODR(BOARD_LED_HEARTBEAT_PORT) ^= 1u << BOARD_LED_HEARTBEAT_PIN;
        }
        char c;
        while (uart_getc(&c)) {
            if (c == '\r' || c == '\n') {
                line[len] = 0;
                if (len) handle_line(line);
                len = 0;
            } else if (len < sizeof line - 1) {
                line[len++] = c;
            }
        }
        wait_for_interrupt();
    }
}
